fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    // The separator is guaranteed to be non-empty
    for s in a {
        if maxsplit == 0 {
            // No splitting performed
            result.push(vec![s]);
            continue;
        }
        
        if s.is_empty() {
            // Empty string results in a single empty string
            result.push(vec![String::new()]);
            continue;
        }
        
        let mut parts = Vec::new();
        let mut remaining = s.as_str();
        let mut splits_remaining = maxsplit as usize;
        
        // Perform right-split by searching from the right
        while splits_remaining > 0 {
            if let Some(pos) = remaining.rfind(&sep) {
                // Split at the found position
                let (right, left) = remaining.split_at(pos);
                parts.push(String::from(&left[sep.len()..])); // part after separator
                remaining = right;
                splits_remaining -= 1;
            } else {
                // No more separators found
                break;
            }
        }
        
        // Add the remaining part (leftmost part)
        parts.push(String::from(remaining));
        
        // Reverse to get correct order (since we built from right to left)
        parts.reverse();
        result.push(parts);
    }
    
    result
}